package com.vandorlabs.neoforge.light;
import com.vandorlabs.neoforge.client.NativeLightScreen;
import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
/** Actual native Light widgets, atlas, slider dragging, picker scrolling, resize and reload. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class LightScreenChecks {
 private static final NativeLightBlock[] BLOCKS=new NativeLightBlock[3];private static BlockEntityType<NativeLightEntity> TYPE;private static final List<NativeLightSettingsEdit> EDITS=new ArrayList<>();private static NativeLightScreen screen;
 private static int ticks,stage,checks,frames;private static String capture;private static boolean captured;private static java.util.concurrent.CompletableFuture<Void> reload;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_LIGHT_SCREEN_CHECK"));}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var kind:NativeLightBlock.Kind.values()){int i=kind.ordinal();BLOCKS[i]=NativeLightBlock.create(kind,BlockBehaviour.Properties.of(),()->TYPE);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","light_screen_fixture_"+i),BLOCKS[i]);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeLightEntity>of((p,s)->new NativeLightEntity(TYPE,p,s,com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE),BLOCKS).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","light_screen_fixture"),TYPE);});}}
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Light screen stage="+stage+": "+text);}
 private static void click(int id,int button){var widget=screen.button(id);need(widget!=null&&widget.active,"enabled button "+id);need(screen.mouseClicked(widget.getX()+widget.getWidth()/2D,widget.getY()+widget.getHeight()/2D,button),"actual click "+id);}
 private static void open(Minecraft mc,int family){var tile=new NativeLightEntity(TYPE,BlockPos.ZERO,BLOCKS[family].defaultBlockState(),com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE);screen=new NativeLightScreen(new NativeLightMenu(null,37,tile),new Inventory(null),Component.literal(family==1?"Programmable Light Frame":family==2?"Programmable Light Slab":"Programmable Light"),EDITS::add);screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
 private static void widgets(Minecraft mc){open(mc,0);need(screen.page()==0&&screen.button(103)==null&&screen.activePicker()!=null&&screen.slider()!=null,"full Light ON controls without Frame size");int layout=screen.choices().layout();click(104,1);need(screen.choices().layout()==Math.floorMod(layout-1,3),"right-click previous texture layout");click(101,1);need(screen.choices().join(),"right-click joins boolean");var slider=screen.slider();need(screen.mouseClicked(slider.getX()+4,slider.getY()+6,0),"brightness slider press");need(screen.mouseDragged(slider.getX()+slider.getWidth()-4,slider.getY()+6,0,100,0),"brightness slider drag");screen.mouseReleased(0,0,0);need(screen.choices().level()==15&&screen.sliderLabel().equals("Light level: 15"),"slider endpoint brightness and display actual="+screen.choices().level()+" label="+screen.sliderLabel());
 click(91,0);need(screen.activePicker()!=null&&screen.slider()==null&&screen.button(105)!=null&&!screen.button(105).active,"OFF automatic default and no slider");screen.choose(78);need(screen.choices().offFaceTexture()==78&&screen.button(105).active,"explicit OFF artwork");click(105,0);need(screen.choices().offFaceTexture()==-1&&!screen.button(105).active,"automatic OFF restoration");click(92,0);screen.choose(0);need(screen.choices().housing()==0&&screen.choices().faceTexture()==78,"Sides choice independent from ON artwork");
 click(93,0);need(screen.activePicker()==null&&screen.button(101)==null&&screen.button(102)!=null,"only Source receive/activation controls on Redstone");int sent=EDITS.size();screen.channelField().setValue("31,");need(!screen.button(100).active&&EDITS.size()==sent,"invalid draft disables Done without send");click(102,1);need(screen.choices().signalBrightness()&&screen.choices().trigger()==2&&EDITS.size()==sent,"reverse Manual selects numeric; malformed draft suppresses all sends");screen.channelField().setValue("31, 32");need(screen.button(100).active&&EDITS.get(EDITS.size()-1).channels().equals(ChannelList.of(31,32))&&EDITS.get(EDITS.size()-1).choices().signalBrightness(),"valid bank sends complete pending choices");
 int[] largeIds=java.util.stream.IntStream.range(0,64).map(i->1000000000+i).toArray();var largeBank=ChannelList.of(largeIds);screen.channelField().setValue(largeBank.toString());need(screen.channelField().getValue().equals(largeBank.toString())&&screen.edit().channels().equals(largeBank)&&screen.button(100).active,"all64 large channel IDs remain intact");screen.channelField().setValue("31, 32");
 click(90,0);slider=screen.slider();need(slider.getIntValue()==0&&screen.sliderLabel().equals("Signal offset: 0"),"numeric offset display");need(screen.mouseClicked(slider.getX()+4,slider.getY()+6,0),"offset slider press");need(screen.choices().offset()==-15,"offset lower bound");need(screen.mouseDragged(slider.getX()+slider.getWidth()-4,slider.getY()+6,0,100,0),"offset slider drag");screen.mouseReleased(0,0,0);need(screen.choices().offset()==15&&screen.sliderLabel().equals("Signal offset: 15"),"offset upper bound and display");
 var picker=screen.activePicker();picker.searchField().setValue("a");picker.searchField().setFocused(true);need(screen.keyPressed(69,0,0),"picker text owns inventory shortcut");int before=picker.scroll();need(screen.mouseScrolled(screen.panel().listX+5,picker.top()+5,0,-1)&&picker.scroll()>before,"picker wheel");int bottom=picker.top()+picker.visible()*22-1;need(screen.mouseClicked(screen.panel().listX+screen.panel().listWidth+2,bottom,0),"scrollbar press");int end=picker.scroll();need(screen.mouseDragged(screen.panel().listX+screen.panel().listWidth+2,picker.top(),0,0,-100)&&picker.scroll()<end,"scrollbar drag");screen.mouseReleased(0,0,0);click(93,0);click(90,0);need(screen.activePicker().searchField().getValue().equals("a"),"tab change retains native picker query");}
 private static void capture(String name){capture=name;captured=false;frames=0;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==9)return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<2200,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"private title-only boundary");if(stage==0){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();stage=1;}else if(stage==1){if(mc.getWindow().getGuiScaledWidth()<600)return;widgets(mc);capture("light-on.png");stage=2;}else if(stage==2&&captured){click(91,0);capture("light-off.png");stage=3;}else if(stage==3&&captured){click(92,0);capture("light-sides.png");stage=4;}else if(stage==4&&captured){click(93,0);capture("light-redstone.png");stage=5;}else if(stage==5&&captured){open(mc,1);need(screen.button(103)!=null,"Frame has size control");click(103,1);need(screen.choices().small(),"Frame reverse size");capture("light-frame.png");stage=6;}else if(stage==6&&captured){screen.activePicker().searchField().setValue("panel");screen.init(mc,400,260);for(int id:new int[]{90,91,92,93,100,101,103,104}){var b=screen.button(id);need(b!=null&&b.getX()>=screen.panel().left&&b.getX()+b.getWidth()<=screen.panel().left+screen.panel().width&&b.getY()>=screen.panel().top&&b.getY()+b.getHeight()<=screen.panel().top+screen.panel().height,"small-screen bounds "+id);}need(screen.activePicker().searchField().getValue().equals("panel"),"resize retains query");reload=mc.reloadResourcePacks();stage=7;}else if(stage==7&&reload.isDone()){reload.join();need(screen.activePicker().searchField().getValue().equals("panel"),"reload retains query");screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());capture("light-reloaded.png");stage=8;}else if(stage==8&&captured){open(mc,2);need(screen.button(103)==null&&screen.slider()!=null,"Slab has Source shared controls without size");need(EDITS.stream().allMatch(e->e.window()==37&&e.pos().equals(BlockPos.ZERO)),"every draft retains exact menu identity");System.out.println("[vandorlabs][light-screen] title PASS checks="+checks+" edits="+EDITS.size());stage=9;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var g=event.getGuiGraphics();g.flush();g.pose().pushPose();try{g.pose().translate(0,0,300);g.fill(0,0,Minecraft.getInstance().getWindow().getGuiScaledWidth(),Minecraft.getInstance().getWindow().getGuiScaledHeight(),0xFF101012);screen.render(g,0,0,0);g.flush();}finally{g.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||++frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->{captured=true;});}
}
